using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-reports"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(GreetingResponse_IsCoherentAndRelevant));

        var chatClient = run.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(FactualQuestion_IsGroundedAndRelevant));

        var chatClient = run.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of using dependency injection in software development?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(MultiTurnConversation_MaintainsCoherence));

        var chatClient = run.ChatConfiguration!.ChatClient;
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to learn about cloud computing.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "Can you go into more detail about serverless architectures?"));

        response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await run.EvaluateAsync(messages);
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // Use the same model as the app host for evaluation
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://your-resource.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        IChatClient chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(deployment)
            .AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

